// ParseError is a CLI parse error. It carries both the "short" first-line
// message and the full "wrapped" message (the suffix that follows
// "invalid command line options: ").
type ParseError struct {
	short   string
	wrapped string // by default equal to short, prefixed with "invalid command line options: "
}

// Short returns the first-line version of the error, as printed at the top
// of the parse-error output.
func (e *ParseError) Short() string {
	return e.short
}

// Wrapped returns the portion appearing after
// "invalid command line options: " in the "Error:" line.
func (e *ParseError) Wrapped() string {
	if e.wrapped != "" {
		return e.wrapped
	}
	return "invalid command line options: " + e.short
}

func (e *ParseError) Error() string {
	return e.short
}

func parseErr(s string) *ParseError {
	return &ParseError{short: s}
}

// ParseOptions parses the given arguments.
func ParseOptions(args []string) (*Options, *ParseError) {
	opts := &Options{}
	positional := make([]string, 0)

	i := 0
	for i < len(args) {
		a := args[i]
		if len(a) >= 2 && a[0] == '-' && a[1] == '-' {
			// Long option
			name := a[2:]
			val := ""
			hasVal := false
			if idx := indexByte(name, '='); idx >= 0 {
				val = name[idx+1:]
				name = name[:idx]
				hasVal = true
			}
			flag, ok := lookupLong(name)
			if !ok {
				return nil, parseErr(fmt.Sprintf("unknown flag `%s'", name))
			}
			if err := applyFlag(opts, flag, hasVal, val, &args, &i); err != nil {
				return nil, err
			}
			i++
			continue
		}
		if len(a) >= 2 && a[0] == '-' && a[1] != '-' {
			// Short option(s). Could be -h, -b10, -b=10, -b 10, -hb
			cursor := 1
			for cursor < len(a) {
				ch := a[cursor]
				flag, ok := lookupShort(ch)
				if !ok {
					return nil, parseErr(fmt.Sprintf("unknown flag `%c'", ch))
				}
				if flag.TakesArg {
					// remainder after this char is either "=val", or "val", or empty (needs next arg)
					rest := a[cursor+1:]
					hasVal := false
					val := ""
					if rest != "" {
						if rest[0] == '=' {
							val = rest[1:]
						} else {
							val = rest
						}
						hasVal = true
					}
					if err := applyFlag(opts, flag, hasVal, val, &args, &i); err != nil {
						return nil, err
					}
					cursor = len(a) // consume remainder
					break
				}
				// bool flag
				if cursor+1 < len(a) && a[cursor+1] == '=' {
					return nil, parseErr(fmt.Sprintf("bool flag `%s' cannot have an argument", flag.Display))
				}
				if err := applyFlag(opts, flag, false, "", &args, &i); err != nil {
					return nil, err
				}
				cursor++
			}
			i++
			continue
		}
		// positional
		positional = append(positional, a)
		i++
	}

	opts.Args = positional
	return opts, nil
