package app

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Config is the configuration for peco.
type Config struct {
	Prompt            string                         `json:"Prompt,omitempty"`
	InitialFilter     string                         `json:"InitialFilter,omitempty"`
	FuzzyLongestSort  bool                           `json:"FuzzyLongestSort,omitempty"`
	StickySelection   bool                           `json:"StickySelection,omitempty"`
	SuppressStatusMsg bool                           `json:"SuppressStatusMsg,omitempty"`
	OnCancel          string                         `json:"OnCancel,omitempty"`
	MaxScanBufferSize int                            `json:"MaxScanBufferSize,omitempty"`
	ANSI              bool                           `json:"ANSI,omitempty"`
	Height            string                         `json:"Height,omitempty"`
	Layout            string                         `json:"Layout,omitempty"`
	SingleKeyJump     map[string]interface{}         `json:"SingleKeyJump,omitempty"`
	SelectionPrefix   string                         `json:"SelectionPrefix,omitempty"`
	Style             map[string]interface{}         `json:"Style,omitempty"`
	Keymap            map[string]interface{}         `json:"Keymap,omitempty"`
	Action            map[string]interface{}         `json:"Action,omitempty"`
	CustomFilter      map[string]interface{}         `json:"CustomFilter,omitempty"`

	// Populated at runtime
	Query string `json:"-"`
}

// LoadConfig loads a config file according to the command line options.
// If --rcfile is given but the file cannot be read, an error is returned.
// Otherwise, it searches standard locations and silently ignores missing files.
func LoadConfig(opts *Options) (*Config, error) {
	cfg := &Config{}
	path := opts.RCFile
	required := opts.RCFileSet

	if path == "" {
		// Search
		path = findConfigFile()
	}
	if path == "" {
		return cfg, nil
	}

	data, err := os.ReadFile(path)
	if err != nil {
		if required {
			return nil, fmt.Errorf("failed to setup configuration: failed to read config file: failed to open file %s: %s", path, unwrapOpen(err))
		}
		// ignore missing standard paths
		return cfg, nil
	}

	// Decide JSON vs YAML.
	if isYAML(path) {
		if err := unmarshalYAML(data, cfg); err != nil {
			return nil, fmt.Errorf("failed to setup configuration: failed to read config file: failed to decode YAML: %s", err)
		}
		return cfg, nil
	}
	if err := json.Unmarshal(data, cfg); err != nil {
		return nil, fmt.Errorf("failed to setup configuration: failed to read config file: failed to decode JSON: %s", err)
	}
	return cfg, nil
}

// unwrapOpen formats an os open error roughly like Go's default.
func unwrapOpen(err error) string {
	return err.Error()
}

func isYAML(path string) bool {
	e := strings.ToLower(filepath.Ext(path))
	return e == ".yaml" || e == ".yml"
}

// findConfigFile looks for a peco config in standard locations.
func findConfigFile() string {
	// 1. $XDG_CONFIG_HOME/peco/config.{json,yaml}
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		for _, name := range []string{"config.json", "config.yaml"} {
			p := filepath.Join(xdg, "peco", name)
			if fileExists(p) {
				return p
			}
		}
	}
	// 2. $HOME/.config/peco/config.{json,yaml}
	if home := os.Getenv("HOME"); home != "" {
		for _, name := range []string{"config.json", "config.yaml"} {
			p := filepath.Join(home, ".config", "peco", name)
			if fileExists(p) {
				return p
			}
		}
	}
	// 3. $XDG_CONFIG_DIRS each
	if xdgd := os.Getenv("XDG_CONFIG_DIRS"); xdgd != "" {
		for _, d := range strings.Split(xdgd, ":") {
			for _, name := range []string{"config.json", "config.yaml"} {
				p := filepath.Join(d, "peco", name)
				if fileExists(p) {
					return p
				}
			}
		}
	}
	// 4. $HOME/.peco/config.{json,yaml}
	if home := os.Getenv("HOME"); home != "" {
		for _, name := range []string{"config.json", "config.yaml"} {
			p := filepath.Join(home, ".peco", name)
			if fileExists(p) {
				return p
			}
		}
	}
	return ""
}

func fileExists(p string) bool {
	st, err := os.Stat(p)
	return err == nil && !st.IsDir()
}

// Apply applies options and config post-load validation.
// Returns errors like the original.
func Apply(cfg *Config, opts *Options) error {
	// on-cancel
	oc := opts.OnCancel
	if !opts.OnCancelSet && cfg.OnCancel != "" {
		oc = cfg.OnCancel
	}
	if oc != "" && oc != "success" && oc != "error" {
		return fmt.Errorf("invalid --on-cancel value: invalid OnCancel value %q: must be %q or %q", oc, "success", "error")
	}

	// initial-filter
	if opts.InitialFilterSet || cfg.InitialFilter != "" {
		name := opts.InitialFilter
		if !opts.InitialFilterSet {
			name = cfg.InitialFilter
		}
		if !isValidFilterName(name) {
			return fmt.Errorf("failed to populate initial filter: failed to set filter: specified filter was not found")
		}
	}

	// height
	if opts.HeightSet {
		if err := validateHeight(opts.Height); err != nil {
			return fmt.Errorf("failed to parse height specification: %s", err)
		}
	} else if cfg.Height != "" {
		if err := validateHeight(cfg.Height); err != nil {
			return fmt.Errorf("failed to parse height specification: %s", err)
		}
	}

	return nil
}

func isValidFilterName(name string) bool {
	switch name {
	case "IgnoreCase", "CaseSensitive", "SmartCase", "IRegexp", "Regexp", "Fuzzy":
		return true
	}
	return false
}
