cat > internal/app/yaml.go <<'EOF'
package app

import (
	"bufio"
	"bytes"
	"fmt"
	"strconv"
	"strings"
)

// unmarshalYAML is a minimal YAML parser sufficient for simple peco configs.
// It supports key: value mappings of the top-level Config struct using the
// same field names; nested maps are stored as generic maps.
func unmarshalYAML(data []byte, cfg *Config) error {
	// Only support flat "key: value" pairs for string/int/bool and simple maps.
	sc := bufio.NewScanner(bytes.NewReader(data))
	lineNo := 0
	for sc.Scan() {
		lineNo++
		line := strings.TrimRight(sc.Text(), " \t")
		if line == "" || strings.HasPrefix(strings.TrimLeft(line, " \t"), "#") {
			continue
		}
		if strings.HasPrefix(line, " ") || strings.HasPrefix(line, "\t") {
			return fmt.Errorf("[%d:1] unexpected indentation", lineNo)
		}
		idx := strings.Index(line, ":")
		if idx < 0 {
			return fmt.Errorf("[%d:1] expected key:value", lineNo)
		}
		key := strings.TrimSpace(line[:idx])
		val := strings.TrimSpace(line[idx+1:])
		// Quick check for unusual structures we cannot handle
		if strings.HasPrefix(val, "- ") || val == "-" {
			col := idx + 2
			for col < len(line) && (line[col] == ' ' || line[col] == '\t') {
				col++
			}
			col++
			return fmt.Errorf("[%d:%d] block sequence entries are not allowed in this context\n>  %d | %s\n%s^", lineNo, col, lineNo, line, strings.Repeat(" ", len(fmt.Sprintf("%d", lineNo))+col+3))
		}
		if err := assignYAML(cfg, key, val, lineNo); err != nil {
			return err
		}
	}
	if err := sc.Err(); err != nil {
		return err
	}
	return nil
}

func assignYAML(cfg *Config, key, rawVal string, lineNo int) error {
	val := rawVal
	// strip quotes
	if len(val) >= 2 && ((val[0] == '"' && val[len(val)-1] == '"') || (val[0] == '\'' && val[len(val)-1] == '\'')) {
		val = val[1 : len(val)-1]
	}
	switch key {
	case "Prompt":
		cfg.Prompt = val
	case "InitialFilter":
		cfg.InitialFilter = val
	case "OnCancel":
		cfg.OnCancel = val
	case "SelectionPrefix":
		cfg.SelectionPrefix = val
	case "Height":
		cfg.Height = val
	case "Layout":
		cfg.Layout = val
	case "FuzzyLongestSort":
		b, err := strconv.ParseBool(val)
		if err != nil {
			return fmt.Errorf("[%d:1] invalid bool: %s", lineNo, val)
		}
		cfg.FuzzyLongestSort = b
	case "StickySelection":
		b, err := strconv.ParseBool(val)
		if err != nil {
			return fmt.Errorf("[%d:1] invalid bool: %s", lineNo, val)
		}
		cfg.StickySelection = b
	case "SuppressStatusMsg":
		b, err := strconv.ParseBool(val)
		if err != nil {
			return fmt.Errorf("[%d:1] invalid bool: %s", lineNo, val)
		}
		cfg.SuppressStatusMsg = b
	case "ANSI":
		b, err := strconv.ParseBool(val)
		if err != nil {
			return fmt.Errorf("[%d:1] invalid bool: %s", lineNo, val)
		}
		cfg.ANSI = b
	case "MaxScanBufferSize":
		n, err := strconv.Atoi(val)
		if err != nil {
			return fmt.Errorf("[%d:1] invalid int: %s", lineNo, val)
		}
		cfg.MaxScanBufferSize = n
	default:
		// Unknown top-level key: ignore
	}
	return nil
}
