package app

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

// InputLine is a single input line from stdin or file.
type InputLine struct {
	Display string // the string to display / search against
	Output  string // the string to emit on selection (may be same as Display)
	Raw     string // the original raw input line (with ANSI codes if any)
}

// OpenInput determines the input source for peco: the file given in positional
// args, or stdin when no file is specified.
func OpenInput(opts *Options) (io.Reader, io.Closer, error) {
	if len(opts.Args) > 0 {
		p := opts.Args[0]
		f, err := os.Open(p)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to open file for input: %s", err.Error())
		}
		return f, f, nil
	}
	return os.Stdin, nil, nil
}

// ReadInput reads lines from r and sends them to out until EOF.
func ReadInput(r io.Reader, opts *Options, out chan<- InputLine) {
	scanner := bufio.NewScanner(r)
	// Allow large lines up to 256KB by default (MaxScanBufferSize config).
	max := 256 * 1024
	scanner.Buffer(make([]byte, 64*1024), max)
	for scanner.Scan() {
		line := scanner.Text()
		l := InputLine{Display: line, Output: line, Raw: line}
		if opts.Null {
			// The first NUL splits display from output.
			for i := 0; i < len(line); i++ {
				if line[i] == 0 {
					l.Display = line[:i]
					l.Output = line[i+1:]
					break
				}
			}
		}
		out <- l
	}
}
