	scanner := bufio.NewScanner(r)
	// Allow large lines up to 256KB by default (MaxScanBufferSize config).
	max := 256 * 1024
	scanner.Buffer(make([]byte, 64*1024), max)
	for scanner.Scan() {
		line := scanner.Text()
		l := InputLine{Display: line, Output: line, Raw: line}
		if opts.Null {
			// The first NUL splits display from output.
			for i := 0; i < len(line); i++ {
				if line[i] == 0 {
					l.Display = line[:i]
					l.Output = line[i+1:]
					break
				}
			}
		}
		out <- l
	}
}
