	if home := os.Getenv("HOME"); home != "" {
		for _, name := range []string{"config.json", "config.yaml"} {
			p := filepath.Join(home, ".config", "peco", name)
			if fileExists(p) {
				return p
			}
		}
	}
	// 3. $XDG_CONFIG_DIRS each
	if xdgd := os.Getenv("XDG_CONFIG_DIRS"); xdgd != "" {
		for _, d := range strings.Split(xdgd, ":") {
			for _, name := range []string{"config.json", "config.yaml"} {
				p := filepath.Join(d, "peco", name)
				if fileExists(p) {
					return p
				}
			}
		}
	}
	// 4. $HOME/.peco/config.{json,yaml}
	if home := os.Getenv("HOME"); home != "" {
		for _, name := range []string{"config.json", "config.yaml"} {
			p := filepath.Join(home, ".peco", name)
			if fileExists(p) {
				return p
			}
		}
	}
	return ""
}

func fileExists(p string) bool {
	st, err := os.Stat(p)
	return err == nil && !st.IsDir()
}

// Apply applies options and config post-load validation.
// Returns errors like the original.
func Apply(cfg *Config, opts *Options) error {
	// on-cancel
	oc := opts.OnCancel
	if !opts.OnCancelSet && cfg.OnCancel != "" {
		oc = cfg.OnCancel
	}
	if oc != "" && oc != "success" && oc != "error" {
		return fmt.Errorf("invalid --on-cancel value: invalid OnCancel value %q: must be %q or %q", oc, "success", "error")
	}

	// initial-filter
	if opts.InitialFilterSet || cfg.InitialFilter != "" {
		name := opts.InitialFilter
		if !opts.InitialFilterSet {
			name = cfg.InitialFilter
		}
		if !isValidFilterName(name) {
			return fmt.Errorf("failed to populate initial filter: failed to set filter: specified filter was not found")
		}
	}

	// height
	if opts.HeightSet {
		if err := validateHeight(opts.Height); err != nil {
			return fmt.Errorf("failed to parse height specification: %s", err)
		}
	} else if cfg.Height != "" {
		if err := validateHeight(cfg.Height); err != nil {
			return fmt.Errorf("failed to parse height specification: %s", err)
		}
	}

	return nil
}

func isValidFilterName(name string) bool {
	switch name {
	case "IgnoreCase", "CaseSensitive", "SmartCase", "IRegexp", "Regexp", "Fuzzy":
		return true
	}
	return false
}
