package app

import (
	"fmt"
	"strconv"
	"strings"
)

// validateHeight parses and validates a --height / Height config value.
// Matching the original error wording used when invalid.
func validateHeight(s string) error {
	if s == "" {
		return fmt.Errorf("invalid height specification: %q", s)
	}
	if strings.HasSuffix(s, "%") {
		body := s[:len(s)-1]
		pct, err := strconv.Atoi(body)
		if err != nil {
			return fmt.Errorf("invalid height specification: %q", s)
		}
		if pct <= 0 {
			return fmt.Errorf("height must be positive: %q", s)
		}
		if pct > 100 {
			return fmt.Errorf("height percentage must not exceed 100: %q", s)
		}
		return nil
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return fmt.Errorf("invalid height specification: %q", s)
	}
	if n <= 0 {
		return fmt.Errorf("height must be positive: %q", s)
	}
	return nil
}
EOF

