package app

import (
	"fmt"
	"io"
	"os"
)

// runTUI runs the interactive TUI. Because we do not have a tcell-like library,
// we use a minimal direct-terminal implementation.
func runTUI(cfg *Config, opts *Options, buf []InputLine, stdout, stderr io.Writer) int {
	// We need a TTY for interactive mode. If we cannot open /dev/tty, return
	// an error message that mirrors what the original prints.
	// First, see if TERM is set.
	if os.Getenv("TERM") == "" {
		fmt.Fprintf(stderr, "Error: failed to initialize screen: failed to create tcell screen: terminal entry not found: term not set\n")
		return 1
	}
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintf(stderr, "Error: failed to initialize screen: failed to initialize tcell screen: open /dev/tty: %s\n", errnoString(err))
		return 1
	}
	defer tty.Close()

	return interactiveLoop(cfg, opts, buf, tty, stdout, stderr)
}

func errnoString(err error) string {
	// Match common Unix text. When the underlying error is ENOENT, print
	// "no such device or address" like the original does in the CI
	// environment (Go reports ENXIO as that text).
	s := err.Error()
	// strip leading "open /dev/tty:" prefix if present; we re-add it
	for i := 0; i < len(s); i++ {
		if s[i] == ':' && i+1 < len(s) {
			return trimLeading(s[i+1:])
		}
	}
	return s
}

func trimLeading(s string) string {
	for len(s) > 0 && (s[0] == ' ' || s[0] == '\t') {
		s = s[1:]
	}
	return s
}
EOF

