package app

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
)

// interactiveLoop implements the TUI.
func interactiveLoop(cfg *Config, opts *Options, buf []InputLine, tty *os.File, stdout, stderr io.Writer) int {
	// Enter raw mode on the TTY so we can read one key at a time.
	oldTermios, err := enterRawMode(int(tty.Fd()))
	if err != nil {
		fmt.Fprintf(stderr, "Error: failed to initialize screen: %s\n", err.Error())
		return 1
	}
	defer func() {
		setTermios(int(tty.Fd()), oldTermios)
		// Leave alternate screen & show cursor.
		tty.WriteString("\x1b[?1049l\x1b[?25h")
	}()
	// Enter alternate screen and hide cursor.
	tty.WriteString("\x1b[?1049h\x1b[?25l")

	st := newState(cfg, opts, buf)

	reader := bufio.NewReader(tty)
	for {
		st.redraw(tty)
		action := readKey(reader)
		switch action.kind {
		case actEnter:
			// Finish: print selected line(s) if any, else current cursor line.
			selected := st.selectedLines()
			printLines(stdout, cfg, opts, buf, selected)
			return 0
		case actCancel:
			if st.onCancelError() {
				return 1
			}
			return 0
		case actRune:
			st.insertRune(action.r)
		case actBackspace:
			st.backspace()
		case actDelete:
			st.delete()
		case actLeft:
			st.moveCaret(-1)
		case actRight:
			st.moveCaret(1)
		case actUp:
			st.selectUp()
		case actDown:
			st.selectDown()
		case actHome:
			st.caret = 0
		case actEnd:
			st.caret = len([]rune(st.query))
		case actKillLine:
			st.killEndOfLine()
		case actKillBOL:
			st.killBeginningOfLine()
		case actDeleteWord:
			st.deleteBackwardWord()
		case actPageUp:
			st.pageUp()
		case actPageDown:
			st.pageDown()
		case actRefresh:
			// will be redrawn
		}
	}
}

// state holds the interactive TUI state.
type state struct {
	cfg       *Config
	opts      *Options
	all       []InputLine
	filtered  []int // indexes into all
	cursor    int   // selected line in filtered
	query     string
	caret     int
	filters   []string
	filterIdx int
}

func newState(cfg *Config, opts *Options, buf []InputLine) *state {
	s := &state{
		cfg:     cfg,
		opts:    opts,
		all:     buf,
		query:   opts.Query,
		caret:   len([]rune(opts.Query)),
		filters: []string{"IgnoreCase", "CaseSensitive", "SmartCase", "IRegexp", "Regexp", "Fuzzy"},
	}
	// Initial filter.
	name := "IgnoreCase"
	if opts.InitialFilterSet {
		name = opts.InitialFilter
	} else if cfg.InitialFilter != "" {
		name = cfg.InitialFilter
	}
	for i, f := range s.filters {
		if f == name {
			s.filterIdx = i
		}
	}
	s.applyFilter()
	if opts.InitialIndexSet {
		s.cursor = opts.InitialIndex
		if s.cursor < 0 {
			s.cursor = 0
		}
		if s.cursor >= len(s.filtered) {
			s.cursor = len(s.filtered) - 1
			if s.cursor < 0 {
				s.cursor = 0
			}
		}
	}
	return s
}

func (s *state) applyFilter() {
	s.filtered = s.filtered[:0]
	q := s.query
	if q == "" {
		for i := range s.all {
			s.filtered = append(s.filtered, i)
		}
		return
	}
	terms := strings.Fields(q)
	for i, l := range s.all {
		ok := true
		hay := l.Display
		for _, t := range terms {
			if !matchTerm(hay, t, s.filters[s.filterIdx]) {
				ok = false
				break
			}
		}
		if ok {
			s.filtered = append(s.filtered, i)
		}
	}
	if s.cursor >= len(s.filtered) {
		s.cursor = len(s.filtered) - 1
	}
	if s.cursor < 0 {
		s.cursor = 0
	}
}

func matchTerm(hay, term, filter string) bool {
	switch filter {
	case "IgnoreCase":
		return strings.Contains(strings.ToLower(hay), strings.ToLower(term))
	case "CaseSensitive":
		return strings.Contains(hay, term)
	case "SmartCase":
		if strings.ToLower(term) == term {
			return strings.Contains(strings.ToLower(hay), term)
		}
		return strings.Contains(hay, term)
	case "Fuzzy":
		// simple subsequence match case-insensitive
		h := strings.ToLower(hay)
		t := strings.ToLower(term)
		hi := 0
		for ti := 0; ti < len(t); ti++ {
			found := false
			for ; hi < len(h); hi++ {
				if h[hi] == t[ti] {
					hi++
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
		return true
	default:
		return strings.Contains(strings.ToLower(hay), strings.ToLower(term))
	}
}

func (s *state) redraw(w io.Writer) {
	rows, cols := winSize(1)
	if rows <= 0 {
		rows = 24
	}
	if cols <= 0 {
		cols = 80
	}
	// Clear screen
	fmt.Fprint(w, "\x1b[2J\x1b[H")
	prompt := "QUERY>"
	if s.cfg.Prompt != "" {
		prompt = s.cfg.Prompt
	}
	if s.opts.PromptSet {
		prompt = s.opts.Prompt
	}
	// Header line
	statusRight := fmt.Sprintf("%s [%d (1/1)]", s.filters[s.filterIdx], len(s.filtered))
	q := s.query
	pad := cols - len(prompt) - 1 - len(q) - 1 - len(statusRight)
	if pad < 1 {
		pad = 1
	}
	fmt.Fprintf(w, "%s %s%s%s", prompt, q, strings.Repeat(" ", pad), statusRight)
	// Results
	for i := 0; i < rows-1 && i < len(s.filtered); i++ {
		line := s.all[s.filtered[i]].Display
		if i == s.cursor {
			fmt.Fprintf(w, "\r\n\x1b[7m%s\x1b[0m", truncate(line, cols))
		} else {
			fmt.Fprintf(w, "\r\n%s", truncate(line, cols))
		}
	}
	// Put cursor near prompt
	fmt.Fprintf(w, "\x1b[1;%dH", len(prompt)+1+s.caret+1)
	fmt.Fprint(w, "\x1b[?25h")
}

func truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n]
}

func (s *state) insertRune(r rune) {
	rs := []rune(s.query)
	rs = append(rs[:s.caret], append([]rune{r}, rs[s.caret:]...)...)
	s.query = string(rs)
	s.caret++
	s.applyFilter()
}

func (s *state) backspace() {
	if s.caret == 0 {
		return
	}
	rs := []rune(s.query)
	rs = append(rs[:s.caret-1], rs[s.caret:]...)
	s.query = string(rs)
	s.caret--
	s.applyFilter()
}

func (s *state) delete() {
	rs := []rune(s.query)
	if s.caret >= len(rs) {
		return
	}
	rs = append(rs[:s.caret], rs[s.caret+1:]...)
	s.query = string(rs)
	s.applyFilter()
}

func (s *state) moveCaret(delta int) {
	s.caret += delta
	if s.caret < 0 {
		s.caret = 0
	}
	if n := len([]rune(s.query)); s.caret > n {
		s.caret = n
	}
}

func (s *state) selectUp()   { if s.cursor > 0 { s.cursor-- } }
func (s *state) selectDown() { if s.cursor+1 < len(s.filtered) { s.cursor++ } }
func (s *state) pageUp()     { s.cursor -= 10; if s.cursor < 0 { s.cursor = 0 } }
func (s *state) pageDown()   { s.cursor += 10; if s.cursor >= len(s.filtered) { s.cursor = len(s.filtered) - 1; if s.cursor < 0 { s.cursor = 0 } } }

func (s *state) killEndOfLine() {
	rs := []rune(s.query)
	s.query = string(rs[:s.caret])
	s.applyFilter()
}
func (s *state) killBeginningOfLine() {
	rs := []rune(s.query)
	s.query = string(rs[s.caret:])
	s.caret = 0
	s.applyFilter()
}
func (s *state) deleteBackwardWord() {
	rs := []rune(s.query)
	i := s.caret
	for i > 0 && (rs[i-1] == ' ' || rs[i-1] == '\t') {
		i--
	}
	for i > 0 && !(rs[i-1] == ' ' || rs[i-1] == '\t') {
		i--
	}
	rs = append(rs[:i], rs[s.caret:]...)
	s.query = string(rs)
	s.caret = i
	s.applyFilter()
}

func (s *state) selectedLines() []InputLine {
	if len(s.filtered) == 0 {
		return nil
	}
	if s.cursor < 0 || s.cursor >= len(s.filtered) {
		return nil
	}
	return []InputLine{s.all[s.filtered[s.cursor]]}
}

func (s *state) onCancelError() bool {
	oc := s.opts.OnCancel
	if !s.opts.OnCancelSet && s.cfg.OnCancel != "" {
		oc = s.cfg.OnCancel
	}
	return oc == "error"
}

// readKey reads an action from the terminal.
type keyAction struct {
	kind int
	r    rune
}

const (
	actNone = iota
	actRune
	actEnter
	actCancel
	actBackspace
	actDelete
	actLeft
	actRight
	actUp
	actDown
	actHome
	actEnd
	actKillLine
	actKillBOL
	actDeleteWord
	actPageUp
	actPageDown
	actRefresh
)

func readKey(r *bufio.Reader) keyAction {
	b, err := r.ReadByte()
	if err != nil {
		return keyAction{kind: actCancel}
	}
	switch b {
	case 0x1b: // ESC
		// Could be ESC alone or CSI sequence.
		if r.Buffered() == 0 {
			return keyAction{kind: actCancel}
		}
		next, _ := r.ReadByte()
		if next != '[' && next != 'O' {
			return keyAction{kind: actCancel}
		}
		// Read digits and final
		var seq []byte
		for {
			c, err := r.ReadByte()
			if err != nil {
				return keyAction{kind: actNone}
			}
			seq = append(seq, c)
			if c >= 0x40 && c <= 0x7e {
				break
			}
		}
		switch string(seq) {
		case "A":
			return keyAction{kind: actUp}
		case "B":
			return keyAction{kind: actDown}
		case "C":
			return keyAction{kind: actRight}
		case "D":
			return keyAction{kind: actLeft}
		case "H":
			return keyAction{kind: actHome}
		case "F":
			return keyAction{kind: actEnd}
		case "5~":
			return keyAction{kind: actPageUp}
		case "6~":
			return keyAction{kind: actPageDown}
		case "3~":
			return keyAction{kind: actDelete}
		}
		return keyAction{kind: actNone}
	case 0x0d, 0x0a: // enter
		return keyAction{kind: actEnter}
	case 0x03: // C-c
		return keyAction{kind: actCancel}
	case 0x7f, 0x08: // BS
		return keyAction{kind: actBackspace}
	case 0x01: // C-a
		return keyAction{kind: actHome}
	case 0x05: // C-e
		return keyAction{kind: actEnd}
	case 0x02: // C-b
		return keyAction{kind: actLeft}
	case 0x06: // C-f
		return keyAction{kind: actRight}
	case 0x0b: // C-k
		return keyAction{kind: actKillLine}
	case 0x15: // C-u
		return keyAction{kind: actKillBOL}
	case 0x17: // C-w
		return keyAction{kind: actDeleteWord}
	case 0x0e: // C-n
		return keyAction{kind: actDown}
	case 0x10: // C-p
		return keyAction{kind: actUp}
	case 0x04: // C-d (delete fwd or EOF)
		return keyAction{kind: actDelete}
	case 0x0c: // C-l redraw
		return keyAction{kind: actRefresh}
	default:
		if b >= 0x20 && b < 0x7f {
			return keyAction{kind: actRune, r: rune(b)}
		}
		// multi-byte UTF-8
		if b >= 0xc0 {
			// crude: read more bytes
			var buf []byte
			buf = append(buf, b)
			n := 0
			switch {
			case b&0xe0 == 0xc0:
				n = 1
			case b&0xf0 == 0xe0:
				n = 2
			case b&0xf8 == 0xf0:
				n = 3
			}
			for i := 0; i < n; i++ {
				c, _ := r.ReadByte()
				buf = append(buf, c)
			}
			rs := []rune(string(buf))
			if len(rs) > 0 {
				return keyAction{kind: actRune, r: rs[0]}
			}
		}
		return keyAction{kind: actNone}
	}
}
EOF

