		// Leave alternate screen & show cursor.
		tty.WriteString("\x1b[?1049l\x1b[?25h")
	}()
	// Enter alternate screen and hide cursor.
	tty.WriteString("\x1b[?1049h\x1b[?25l")

	st := newState(cfg, opts, buf)

	reader := bufio.NewReader(tty)
	for {
		st.redraw(tty)
