	query     string
	caret     int
	filters   []string
	filterIdx int
}

func newState(cfg *Config, opts *Options, buf []InputLine) *state {
	s := &state{
		cfg:     cfg,
		opts:    opts,
		all:     buf,
		query:   opts.Query,
		caret:   len([]rune(opts.Query)),
		filters: []string{"IgnoreCase", "CaseSensitive", "SmartCase", "IRegexp", "Regexp", "Fuzzy"},
	}
	// Initial filter.
	name := "IgnoreCase"
	if opts.InitialFilterSet {
		name = opts.InitialFilter
	} else if cfg.InitialFilter != "" {
		name = cfg.InitialFilter
	}
	for i, f := range s.filters {
		if f == name {
			s.filterIdx = i
		}
	}
