		s.cursor = opts.InitialIndex
		if s.cursor < 0 {
			s.cursor = 0
		}
		if s.cursor >= len(s.filtered) {
			s.cursor = len(s.filtered) - 1
			if s.cursor < 0 {
				s.cursor = 0
			}
		}
	}
	return s
