func (s *state) applyFilter() {
	s.filtered = s.filtered[:0]
	q := s.query
	if q == "" {
		for i := range s.all {
			s.filtered = append(s.filtered, i)
		}
		return
	}
	terms := strings.Fields(q)
	for i, l := range s.all {
		ok := true
		hay := l.Display
		for _, t := range terms {
			if !matchTerm(hay, t, s.filters[s.filterIdx]) {
				ok = false
				break
			}
