func matchTerm(hay, term, filter string) bool {
	switch filter {
	case "IgnoreCase":
		return strings.Contains(strings.ToLower(hay), strings.ToLower(term))
	case "CaseSensitive":
		return strings.Contains(hay, term)
	case "SmartCase":
		if strings.ToLower(term) == term {
			return strings.Contains(strings.ToLower(hay), term)
		}
		return strings.Contains(hay, term)
	case "Fuzzy":
		// simple subsequence match case-insensitive
		h := strings.ToLower(hay)
		t := strings.ToLower(term)
		hi := 0
		for ti := 0; ti < len(t); ti++ {
			found := false
			for ; hi < len(h); hi++ {
				if h[hi] == t[ti] {
