	rs = append(rs[:s.caret-1], rs[s.caret:]...)
	s.query = string(rs)
	s.caret--
	s.applyFilter()
}

func (s *state) delete() {
	rs := []rune(s.query)
	if s.caret >= len(rs) {
		return
	}
	rs = append(rs[:s.caret], rs[s.caret+1:]...)
	s.query = string(rs)
	s.applyFilter()
}

