	rs := []rune(s.query)
	s.query = string(rs[:s.caret])
	s.applyFilter()
}
func (s *state) killBeginningOfLine() {
	rs := []rune(s.query)
	s.query = string(rs[s.caret:])
	s.caret = 0
	s.applyFilter()
}
func (s *state) deleteBackwardWord() {
	rs := []rune(s.query)
	i := s.caret
	for i > 0 && (rs[i-1] == ' ' || rs[i-1] == '\t') {
		i--
	}
	for i > 0 && !(rs[i-1] == ' ' || rs[i-1] == '\t') {
		i--
	}
	rs = append(rs[:i], rs[s.caret:]...)
	s.query = string(rs)
	s.caret = i
	s.applyFilter()
}

func (s *state) selectedLines() []InputLine {
	if len(s.filtered) == 0 {
		return nil
	}
	if s.cursor < 0 || s.cursor >= len(s.filtered) {
		return nil
	}
	return []InputLine{s.all[s.filtered[s.cursor]]}
}

func (s *state) onCancelError() bool {
	oc := s.opts.OnCancel
	if !s.opts.OnCancelSet && s.cfg.OnCancel != "" {
		oc = s.cfg.OnCancel
	}
	return oc == "error"
}

// readKey reads an action from the terminal.
type keyAction struct {
	kind int
	r    rune
}

const (
	actNone = iota
	actRune
	actEnter
	actCancel
	actBackspace
	actDelete
	actLeft
	actRight
	actUp
	actDown
	actHome
	actEnd
	actKillLine
	actKillBOL
	actDeleteWord
	actPageUp
	actPageDown
	actRefresh
)

func readKey(r *bufio.Reader) keyAction {
	b, err := r.ReadByte()
	if err != nil {
		return keyAction{kind: actCancel}
	}
	switch b {
	case 0x1b: // ESC
		// Could be ESC alone or CSI sequence.
		if r.Buffered() == 0 {
			return keyAction{kind: actCancel}
		}
		next, _ := r.ReadByte()
		if next != '[' && next != 'O' {
			return keyAction{kind: actCancel}
		}
		// Read digits and final
		var seq []byte
		for {
			c, err := r.ReadByte()
			if err != nil {
				return keyAction{kind: actNone}
			}
			seq = append(seq, c)
			if c >= 0x40 && c <= 0x7e {
				break
			}
		}
		switch string(seq) {
		case "A":
			return keyAction{kind: actUp}
		case "B":
			return keyAction{kind: actDown}
		case "C":
			return keyAction{kind: actRight}
		case "D":
			return keyAction{kind: actLeft}
		case "H":
			return keyAction{kind: actHome}
		case "F":
			return keyAction{kind: actEnd}
		case "5~":
			return keyAction{kind: actPageUp}
		case "6~":
			return keyAction{kind: actPageDown}
		case "3~":
			return keyAction{kind: actDelete}
		}
		return keyAction{kind: actNone}
	case 0x0d, 0x0a: // enter
		return keyAction{kind: actEnter}
	case 0x03: // C-c
		return keyAction{kind: actCancel}
	case 0x7f, 0x08: // BS
		return keyAction{kind: actBackspace}
	case 0x01: // C-a
		return keyAction{kind: actHome}
	case 0x05: // C-e
		return keyAction{kind: actEnd}
	case 0x02: // C-b
		return keyAction{kind: actLeft}
	case 0x06: // C-f
		return keyAction{kind: actRight}
	case 0x0b: // C-k
		return keyAction{kind: actKillLine}
	case 0x15: // C-u
		return keyAction{kind: actKillBOL}
	case 0x17: // C-w
		return keyAction{kind: actDeleteWord}
	case 0x0e: // C-n
		return keyAction{kind: actDown}
	case 0x10: // C-p
		return keyAction{kind: actUp}
	case 0x04: // C-d (delete fwd or EOF)
		return keyAction{kind: actDelete}
	case 0x0c: // C-l redraw
		return keyAction{kind: actRefresh}
	default:
		if b >= 0x20 && b < 0x7f {
			return keyAction{kind: actRune, r: rune(b)}
		}
		// multi-byte UTF-8
		if b >= 0xc0 {
			// crude: read more bytes
			var buf []byte
			buf = append(buf, b)
			n := 0
			switch {
			case b&0xe0 == 0xc0:
				n = 1
			case b&0xf0 == 0xe0:
				n = 2
			case b&0xf8 == 0xf0:
				n = 3
			}
			for i := 0; i < n; i++ {
				c, _ := r.ReadByte()
				buf = append(buf, c)
			}
			rs := []rune(string(buf))
			if len(rs) > 0 {
				return keyAction{kind: actRune, r: rs[0]}
			}
		}
		return keyAction{kind: actNone}
	}
}
