	rs = append(rs[:s.caret], append([]rune{r}, rs[s.caret:]...)...)
	s.query = string(rs)
	s.caret++
	s.applyFilter()
}

func (s *state) backspace() {
	if s.caret == 0 {
		return
	}
	rs := []rune(s.query)
	rs = append(rs[:s.caret-1], rs[s.caret:]...)
	s.query = string(rs)
	s.caret--
	s.applyFilter()
}

func (s *state) delete() {
	rs := []rune(s.query)
	if s.caret >= len(rs) {
		return
	}
	rs = append(rs[:s.caret], rs[s.caret+1:]...)
	s.query = string(rs)
	s.applyFilter()
}

func (s *state) moveCaret(delta int) {
	s.caret += delta
	if s.caret < 0 {
		s.caret = 0
	}
	if n := len([]rune(s.query)); s.caret > n {
		s.caret = n
	}
}

func (s *state) selectUp()   { if s.cursor > 0 { s.cursor-- } }
func (s *state) selectDown() { if s.cursor+1 < len(s.filtered) { s.cursor++ } }
func (s *state) pageUp()     { s.cursor -= 10; if s.cursor < 0 { s.cursor = 0 } }
func (s *state) pageDown() {
	s.cursor += 10
	if s.cursor >= len(s.filtered) {
		s.cursor = len(s.filtered) - 1
		if s.cursor < 0 {
			s.cursor = 0
		}
	}
}

