	actRight
	actUp
	actDown
	actHome
	actEnd
	actKillLine
	actKillBOL
	actDeleteWord
	actPageUp
	actPageDown
	actRefresh
)

func readKey(r *bufio.Reader) keyAction {
	b, err := r.ReadByte()
	if err != nil {
		return keyAction{kind: actCancel}
	}
	switch b {
	case 0x1b:
		if r.Buffered() == 0 {
			return keyAction{kind: actCancel}
		}
		next, _ := r.ReadByte()
		if next != '[' && next != 'O' {
			return keyAction{kind: actCancel}
		}
		var seq []byte
		for {
			c, err := r.ReadByte()
			if err != nil {
				return keyAction{kind: actNone}
			}
			seq = append(seq, c)
			if c >= 0x40 && c <= 0x7e {
				break
			}
		}
		switch string(seq) {
		case "A":
			return keyAction{kind: actUp}
		case "B":
			return keyAction{kind: actDown}
		case "C":
			return keyAction{kind: actRight}
		case "D":
			return keyAction{kind: actLeft}
		case "H":
			return keyAction{kind: actHome}
		case "F":
			return keyAction{kind: actEnd}
		case "5~":
			return keyAction{kind: actPageUp}
		case "6~":
			return keyAction{kind: actPageDown}
		case "3~":
			return keyAction{kind: actDelete}
		}
		return keyAction{kind: actNone}
	case 0x0d, 0x0a:
		return keyAction{kind: actEnter}
	case 0x03:
		return keyAction{kind: actCancel}
	case 0x7f, 0x08:
		return keyAction{kind: actBackspace}
	case 0x01:
		return keyAction{kind: actHome}
	case 0x05:
		return keyAction{kind: actEnd}
	case 0x02:
		return keyAction{kind: actLeft}
	case 0x06:
		return keyAction{kind: actRight}
	case 0x0b:
		return keyAction{kind: actKillLine}
	case 0x15:
		return keyAction{kind: actKillBOL}
	case 0x17:
		return keyAction{kind: actDeleteWord}
	case 0x0e:
		return keyAction{kind: actDown}
	case 0x10:
		return keyAction{kind: actUp}
	case 0x04:
		return keyAction{kind: actDelete}
	case 0x0c:
		return keyAction{kind: actRefresh}
	default:
		if b >= 0x20 && b < 0x7f {
			return keyAction{kind: actRune, r: rune(b)}
		}
		if b >= 0xc0 {
			var buf []byte
			buf = append(buf, b)
			n := 0
			switch {
			case b&0xe0 == 0xc0:
				n = 1
			case b&0xf0 == 0xe0:
				n = 2
			case b&0xf8 == 0xf0:
				n = 3
			}
			for i := 0; i < n; i++ {
				c, _ := r.ReadByte()
				buf = append(buf, c)
			}
			rs := []rune(string(buf))
			if len(rs) > 0 {
				return keyAction{kind: actRune, r: rs[0]}
			}
		}
		return keyAction{kind: actNone}
	}
}
