// interactiveLoop implements the TUI.
func interactiveLoop(cfg *Config, opts *Options, buf []InputLine, tty *os.File, stdout, stderr io.Writer) int {
	oldTermios, err := enterRawMode(int(tty.Fd()))
	if err != nil {
		fmt.Fprintf(stderr, "Error: failed to initialize screen: %s\n", err.Error())
		return 1
	}
	restored := false
	restore := func() {
		if restored {
			return
		}
		restored = true
		setTermios(int(tty.Fd()), oldTermios)
		tty.WriteString("\x1b[?1049l\x1b[?25h")
	}
	defer restore()
	tty.WriteString("\x1b[?1049h\x1b[?25l")

	st := newState(cfg, opts, buf)

	reader := bufio.NewReader(tty)
	for {
		st.redraw(tty)
		action := readKey(reader)
		switch action.kind {
		case actEnter:
			selected := st.selectedLines()
			restore()
			printLines(stdout, cfg, opts, buf, selected)
			return 0
		case actCancel:
			restore()
			if st.onCancelError() {
				return 1
			}
			return 0
		case actRune:
			st.insertRune(action.r)
		case actBackspace:
			st.backspace()
		case actDelete:
			st.delete()
		case actLeft:
			st.moveCaret(-1)
		case actRight:
			st.moveCaret(1)
		case actUp:
			st.selectUp()
		case actDown:
			st.selectDown()
		case actHome:
			st.caret = 0
		case actEnd:
