package app

import (
	"fmt"
	"io"
	"os"
	"strings"
)

// Version is the version of this peco binary.
const Version = "v0.5.11"

// goVersion is the reported Go toolchain version.
const goVersion = "go1.25.0"

// Run executes the peco CLI with the given args (excluding argv[0]).
func Run(args []string) int {
	stdout := os.Stdout
	stderr := os.Stderr

	opts, parseErr := ParseOptions(args)
	if parseErr != nil {
		fmt.Fprintf(stderr, "%s\n", parseErr.Short())
		fmt.Fprint(stderr, UsageString())
		fmt.Fprintf(stderr, "Error: failed to setup peco: failed to parse command line: failed to parse command line options: %s\n", parseErr.Wrapped())
		return 1
	}

	if opts.Help {
		fmt.Fprint(stdout, UsageString())
		return 0
	}

	if opts.Version {
		fmt.Fprintf(stdout, "peco version %s (built with %s)\n", Version, goVersion)
		return 0
	}

	return run(opts, stdout, stderr)
}

func run(opts *Options, stdout, stderr io.Writer) int {
	cfg, err := LoadConfig(opts)
	if err != nil {
		fmt.Fprintf(stderr, "Error: failed to setup peco: %s\n", err)
		return 1
	}

	if opts.LayoutSet {
		switch opts.Layout {
		case "top-down", "bottom-up", "top-down-query-bottom":
		default:
			fmt.Fprintf(stderr, "Error: failed to setup peco: failed to parse command line: failed to parse command line options: invalid command line arguments: unknown layout: '%s'\n", opts.Layout)
			return 1
		}
	}

	if err := Apply(cfg, opts); err != nil {
		fmt.Fprintf(stderr, "Error: failed to setup peco: failed to apply configuration: %s\n", err)
		return 1
	}

	src, closer, err := OpenInput(opts)
	if err != nil {
		fmt.Fprintf(stderr, "Error: failed to setup input source: %s\n", err)
		return 1
	}
	if closer != nil {
		defer closer.Close()
	}

	// Read all input into an in-memory buffer. We do this synchronously
	// before opening the TUI; while this differs slightly from the original's
	// background-reading race, it makes the fast-path behaviour deterministic.
	lines := make(chan InputLine, 1024)
	go func() {
		defer close(lines)
		ReadInput(src, opts, lines)
	}()

	var buf []InputLine
	for l := range lines {
		if opts.BufferSize > 0 && len(buf) >= opts.BufferSize {
			buf = buf[1:]
		}
		buf = append(buf, l)
	}

	// Fast paths (do not require a TTY).
	if opts.ExitZero && len(buf) == 0 {
		return 1
	}
	if opts.SelectAll {
		return emitSelection(cfg, opts, buf, buf, stdout, stderr)
	}
	if opts.SelectOne && len(buf) == 1 {
		return emitSelection(cfg, opts, buf, buf, stdout, stderr)
	}

	return runTUI(cfg, opts, buf, stdout, stderr)
}

// emitSelection prints (or pipes to --exec) the selected lines and returns.
func emitSelection(cfg *Config, opts *Options, all, sel []InputLine, stdout, stderr io.Writer) int {
	if opts.ExecSet {
		return execSelection(cfg, opts, sel, stdout, stderr)
	}
	printLines(stdout, cfg, opts, all, sel)
	return 0
}

// printLines writes the selected lines to w, optionally prepended by the query.
func printLines(w io.Writer, cfg *Config, opts *Options, all, selected []InputLine) {
	if opts.PrintQuery {
		q := opts.Query
		if q == "" {
			q = cfg.Query
		}
		fmt.Fprintln(w, q)
	}
	for _, l := range selected {
		fmt.Fprintln(w, l.Output)
	}
}

var _ = strings.ToLower
