// execSelection pipes the selected lines through /bin/sh -c <opts.Exec>.
func execSelection(cfg *Config, opts *Options, sel []InputLine, stdout, stderr io.Writer) int {
	cmd := exec.Command("/bin/sh", "-c", opts.Exec)
	in, err := cmd.StdinPipe()
	if err != nil {
