// queryTerm is a single parsed term from the user's query.
type queryTerm struct {
	value  string
	negate bool
}

// parseQueryTerms splits the query into terms, handling backslash escapes and
// negative terms ("-foo" means NOT foo; "\-foo" means literal "-foo").
func parseQueryTerms(q string) []queryTerm {
	fields := strings.Fields(q)
	out := make([]queryTerm, 0, len(fields))
	for _, f := range fields {
		if f == "-" {
			out = append(out, queryTerm{value: "-"})
			continue
		}
		if strings.HasPrefix(f, "\\-") {
			out = append(out, queryTerm{value: f[1:]})
			continue
		}
		if strings.HasPrefix(f, "-") && len(f) > 1 {
			out = append(out, queryTerm{value: f[1:], negate: true})
			continue
		}
		out = append(out, queryTerm{value: f})
	}
	return out
}
