// installSignalHandler installs handlers for SIGWINCH (terminal resize).
// It returns a channel that sends notifications when the terminal size
// changes. SIGINT/SIGTERM handlers are left to restore the terminal
// (handled via defer).
func installSignalHandler() chan os.Signal {
	ch := make(chan os.Signal, 4)
	signal.Notify(ch, syscall.SIGWINCH)
	return ch
}
EOF

